import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.Dg5fKO7V.js";const p=JSON.parse('{"title":"CI and Release","description":"","frontmatter":{},"headers":[],"relativePath":"CI-And-Release.md","filePath":"CI-And-Release.md","lastUpdated":1788563284000}'),r={name:"CI-And-Release.md"};function n(s,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="ci-and-release" tabindex="-1">CI and Release <a class="header-anchor" href="#ci-and-release" aria-label="Permalink to &quot;CI and Release&quot;">​</a></h1><p>Two workflows are committed: one for continuous quality analysis and one for signed releases.</p><h2 id="quality" tabindex="-1">Quality <a class="header-anchor" href="#quality" aria-label="Permalink to &quot;Quality&quot;">​</a></h2><p><code>.github/workflows/quality.yml</code> runs on pushes and pull requests whose changes are not limited to Markdown or the licence.</p><table tabindex="0"><thead><tr><th>Job</th><th>Runs on</th><th>Does</th></tr></thead><tbody><tr><td><code>frontend</code></td><td>Linux</td><td>Prettier, TypeScript, ESLint at zero warnings and Knip</td></tr><tr><td><code>rust</code></td><td>Linux, only when <code>src-tauri</code> or the workflow changed</td><td><code>cargo fmt --check</code> and Clippy at <code>-D warnings</code></td></tr><tr><td><code>sonar-frontend</code></td><td>Linux, when the frontend Sonar variables exist</td><td>Frontend coverage, frontend project checks and the 80% Sonar gate</td></tr><tr><td><code>sonar-backend</code></td><td>Linux, when the backend Sonar variables exist</td><td>Rust coverage, backend project checks, Clippy and the 60% Sonar gate</td></tr></tbody></table><p>The Sonar jobs are inert in forks and before <code>SONAR_ORGANIZATION</code> and their project keys have been configured. Their token is the <code>SONAR_TOKEN</code> Actions secret. The scanners read separate LCOV and external-issue reports, so frontend and backend cannot hide each other&#39;s missing coverage. See <a href="./SonarQube">SonarQube</a> for the local equivalent.</p><p>The workflow does not replace the full executable test gate. Run <code>npm run ci:local</code> before a pull request; <a href="./Testing">Testing</a> lists the focused and network suites.</p><h2 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;Release&quot;">​</a></h2><p><code>.github/workflows/release.yml</code>, triggered by hand with a tag.</p><p><strong>check</strong> runs before any secret is in scope. It verifies the actor is allowed to release, that the tag matches <code>package.json</code>, <code>Cargo.toml</code> and <code>tauri.conf.json</code>, and that the tag does not already exist. The three-way version check matters: the bundler reads <code>tauri.conf.json</code>, so a mismatch there ships installers whose version disagrees with the tag and breaks the updater comparison.</p><p><strong>build</strong> runs on Linux, Windows and macOS with the signing key in scope, produces installers for all three, and fails if no <code>.sig</code> was produced, because an unsigned build cannot be updated into.</p><p>Linux produces a <code>.deb</code>, an <code>.AppImage</code> and an <code>.rpm</code>. The AppImage build removes the complete system WebKit dependency closure before repacking, logs its size before and after, and keeps the original until the replacement succeeds.</p><p><strong>publish</strong> collects every artifact, refuses if two platforms produced the same filename, generates <code>latest.json</code> for the updater, and creates the release as a draft unless you asked for it to be published.</p><h2 id="cutting-a-release" tabindex="-1">Cutting a release <a class="header-anchor" href="#cutting-a-release" aria-label="Permalink to &quot;Cutting a release&quot;">​</a></h2><ol><li>Bump the version in <code>package.json</code>, <code>src-tauri/Cargo.toml</code> and <code>src-tauri/tauri.conf.json</code>.</li><li>Regenerate <code>Cargo.lock</code> with <code>cargo check</code>.</li><li>Update the changelog.</li><li>Run <code>npm run ci:local</code>, merge to <code>main</code> and wait for Quality.</li><li>Run the Release workflow with the tag, for example <code>v2.0.0</code>.</li><li>Review the draft and publish it.</li></ol><p>Build locally first and check it by hand. A green pipeline proves it compiles, not that it works.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>The updater endpoint serves <code>latest.json</code> and the assets. Every download is checked against a public key compiled into the build, so a tampered artifact is refused rather than installed. The repository holding the update assets must stay public and hold nothing but those assets.</p>',18)])])}const f=t(r,[["render",n]]);export{p as __pageData,f as default};
